Method.Implementation:
	#dim tSC As %Status=$$$OK
    set tSC=..Adapter.SetAutoCommit(1) 
    Set pResponse = ##class(IHC.ITF.Response.DwDbInsQueryResponse).%New()

	$$$TRACE("Inside "_..%ConfigName_" Method CategoryLookup: " _ pRequest.FSCNUMBER)

	if ($L(pRequest.FSCNUMBER) > 0){

	    try{	

 	      set tQ = "SELECT NAME, REPORTING_CATEGORY__1, REPORTING_CATEGORY__2, D2.CATEGORY_NAME As CatName1, D3.CATEGORY_NAME As CatName2, D1.INACTIVE_FLAG FROM DBO.DN19 D1 JOIN DBO.DN77 D2 ON D1.REPORTING_CATEGORY__1 = D2.RECORD_NUMBER JOIN DBO.DN77 D3 ON D1.REPORTING_CATEGORY__2 = D3.RECORD_NUMBER WHERE FSC_NUMBER in ( "
 	      SET namelist=$LISTFROMSTRING(pRequest.FSCNUMBER,"#")
 	      $$$TRACE("$LISTLENGTH(namelist): " _ $LISTLENGTH(namelist))

 	      IF ($LISTLENGTH(namelist) > 1)
 	      {
 	      	FOR i=1:1:$LISTLENGTH(namelist) - 1
 	      	{
 	        	set tQ = tQ _ $LISTGET(namelist, i, "#") _ ","
	      	} 
 	      }

	      set tQ = tQ _ $LISTGET(namelist, $LISTLENGTH(namelist), "#")
 	      set tQ = tQ _ " ) AND D1.Inactive_flag = 'N'"

 	      set tSC=..Adapter.ExecuteQuery(.tResult, tQ)
 	      $$$TRACE(tQ  _ "  SUCCESS : "_tSC)		 	   	
	    }CATCH err {		
	      $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	      set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	    }	
	    $$$TRACE(" ExecuteQuery STATUS: "_tSC _ "tResult: "_tResult)
	    While tResult.Next() {

		  set dwDbInsInfo = ##class(IHC.ITF.Response.DwDbInsEntry).%New()
          set dwDbInsInfo.NAME =  tResult.GetData(1)   
          set dwDbInsInfo.CATEGORY1 =  tResult.GetData(2)
          set dwDbInsInfo.CATEGORY2 =  tResult.GetData(3) 
          set dwDbInsInfo.CATEGORYNAME1 =  tResult.GetData(4) 
          set dwDbInsInfo.CATEGORYNAME2 =  tResult.GetData(5)
          set dwDbInsInfo.INACTIVE =  tResult.GetData(6)
          Do pResponse.entries.Insert(dwDbInsInfo)
          $$$TRACE("Insurance added: " _ dwDbInsInfo.NAME)
        }   

	}
	else {
	   set tSC = $$$ERROR( "FSCNUMBER is not valid: " _ pRequest.FSCNUMBER)	    
	}

	$$$TRACE(" DW RESPONSE count : "_ pResponse.entries.Count())	
	quit tSC
